package com.campuspi.member;
import com.campuspi.account.*;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import org.springframework.stereotype.Service;
import static com.campuspi.member.MemberSupport.*;

@Service
public class MemberChatService {
    private final MemberSupport m;
    public MemberChatService(MemberSupport m){this.m=m;}
    private Map<String,Object> session(AccountService.Identity actor,long id,boolean lock){var row=m.require("t_chat_session","session_id",id,lock);if(actor.id()!=number(row,"sender_id")&&actor.id()!=number(row,"receiver_id"))throw new ApiException(404,"会话不存在");return row;}
    private long peer(AccountService.Identity actor,Map<String,Object> row){return number(row,"sender_id")==actor.id()?number(row,"receiver_id"):number(row,"sender_id");}
    private String visible(AccountService.Identity actor){return "((sender_id="+actor.id()+" AND sender_deleted=FALSE) OR (receiver_id="+actor.id()+" AND receiver_deleted=FALSE))";}
    private Object sessionView(AccountService.Identity actor,Map<String,Object> row){
        long id=number(row,"session_id");var last=m.one("SELECT content_type,LEFT(content,200) content,send_time FROM t_private_msg WHERE session_id=? AND "+visible(actor)+" ORDER BY msg_id DESC LIMIT 1",id);long unread=m.db.queryForObject("SELECT COUNT(*) FROM t_private_msg WHERE session_id=? AND receiver_id=? AND read_at IS NULL AND receiver_deleted=FALSE",Long.class,id,actor.id());if(unread>Integer.MAX_VALUE)throw new ApiException(503,"未读消息计数超过上限");var out=new LinkedHashMap<String,Object>();out.put("session_id",Long.toString(id));out.put("peer",m.publicUser(peer(actor,row)));out.put("last_message",last==null?null:"图片".equals(last.get("content_type"))?"[图片]":last.get("content"));out.put("last_send_time",last==null?null:time(last.get("send_time")));out.put("unread_count",(int)unread);return out;
    }
    public Object create(AccountService.Identity actor,JsonNode body){AccountService.fields(body,"peer_user_id");long peer=AccountService.id(AccountService.text(body,"peer_user_id",1,19,false));if(peer==actor.id())throw new ApiException(400,"不能与本人创建私信会话");return m.accounts.memberTransaction(actor,()->{var user=m.require("users","user_id",peer,true);if(!"ACTIVE".equals(user.get("account_status")))throw new ApiException(403,"对方账号已停用");long first=Math.min(actor.id(),peer),second=Math.max(actor.id(),peer);m.db.update("INSERT IGNORE INTO t_chat_session(sender_id,receiver_id) VALUES(?,?)",first,second);return sessionView(actor,m.one("SELECT * FROM t_chat_session WHERE sender_id=? AND receiver_id=?",first,second));});}
    public Object list(AccountService.Identity actor,int page,int size){
        String actorId=Long.toString(actor.id());String visible="((v.sender_id="+actorId+" AND v.sender_deleted=FALSE) OR (v.receiver_id="+actorId+" AND v.receiver_deleted=FALSE))";
        return m.page("t_chat_session s","s.*,(SELECT MAX(v.send_time) FROM t_private_msg v WHERE v.session_id=s.session_id AND "+visible+") last_visible_time"," WHERE s.sender_id=? OR s.receiver_id=?",List.of(actor.id(),actor.id()),page,size,"COALESCE(last_visible_time,s.created_at) DESC,s.session_id DESC",row->sessionView(actor,row));
    }
    private Object messageView(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();for(String field:List.of("msg_id","session_id","sender_id","receiver_id"))out.put(field,string(row.get(field)));for(String field:List.of("content_type","content"))out.put(field,row.get(field));for(String field:List.of("send_time","read_at"))out.put(field,time(row.get(field)));return out;}
    public Object messages(AccountService.Identity actor,long id,int limit,String before,String after){
        session(actor,id,false);if(limit<1||limit>100||!before.isEmpty()&&!after.isEmpty())throw new ApiException(400,"消息数量或游标参数无效");String cursor=before.isEmpty()?after:before;String condition="";var args=new ArrayList<Object>();args.add(id);
        if(!cursor.isEmpty()){long boundary=AccountService.id(cursor);if(m.one("SELECT msg_id FROM t_private_msg WHERE msg_id=? AND session_id=?",boundary,id)==null)throw new ApiException(404,"游标不属于当前会话");condition=before.isEmpty()?" AND msg_id>?":" AND msg_id<?";args.add(boundary);}args.add(limit+1);boolean forward=!after.isEmpty();var rows=m.db.queryForList("SELECT * FROM t_private_msg WHERE session_id=? AND "+visible(actor)+condition+" ORDER BY msg_id "+(forward?"ASC":"DESC")+" LIMIT ?",args.toArray());boolean more=rows.size()>limit;var batch=new ArrayList<>(rows.subList(0,Math.min(limit,rows.size())));if(!forward)Collections.reverse(batch);var out=new LinkedHashMap<String,Object>();out.put("items",batch.stream().map(this::messageView).toList());out.put("has_more",more);out.put("next_before_id",batch.isEmpty()?null:string(batch.get(0).get("msg_id")));out.put("next_after_id",batch.isEmpty()?null:string(batch.get(batch.size()-1).get("msg_id")));return out;
    }
    public Object send(AccountService.Identity actor,long id,JsonNode body,String key){AccountService.fields(body,"content_type","content");String type=text(body,"content_type",1,10),value=text(body,"content",1,2000);choice(type,"文本","图片");if(type.equals("图片"))m.files.refId(value);return m.accounts.memberMutation(actor,"message-send:"+id,key,body,()->{
        var chat=session(actor,id,true);long receiver=peer(actor,chat);var other=m.require("users","user_id",receiver,true);if(!"ACTIVE".equals(other.get("account_status")))throw new ApiException(403,"对方账号已停用");long msg=m.insert("INSERT INTO t_private_msg(session_id,sender_id,receiver_id,content_type,content) VALUES(?,?,?,?,?)",id,actor.id(),receiver,type,value);if(type.equals("图片"))m.files.bindRefs(actor.id(),"CHAT_IMAGE","MESSAGE",Long.toString(msg),List.of(value));return messageView(m.require("t_private_msg","msg_id",msg,false));
    });}
    private Map<String,Object> message(AccountService.Identity actor,long id,boolean visibleOnly){var row=m.require("t_private_msg","msg_id",id,true);session(actor,number(row,"session_id"),false);boolean sender=number(row,"sender_id")==actor.id();if(!sender&&number(row,"receiver_id")!=actor.id()||visibleOnly&&flag(row.get(sender?"sender_deleted":"receiver_deleted")))throw new ApiException(404,"消息不存在");return row;}
    public Object read(AccountService.Identity actor,long id){return m.accounts.memberTransaction(actor,()->{var row=message(actor,id,true);if(number(row,"receiver_id")!=actor.id())throw new ApiException(403,"只有接收者可以标记已读");m.db.update("UPDATE t_private_msg SET read_at=COALESCE(read_at,UTC_TIMESTAMP(3)) WHERE msg_id=?",id);return messageView(m.require("t_private_msg","msg_id",id,false));});}
    public Object delete(AccountService.Identity actor,long id){return m.accounts.memberTransaction(actor,()->{var row=message(actor,id,false);String column=number(row,"sender_id")==actor.id()?"sender_deleted":"receiver_deleted";m.db.update("UPDATE t_private_msg SET "+column+"=TRUE WHERE msg_id=?",id);return null;});}
    private Object reportView(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();for(String field:List.of("report_id","msg_id","reporter_id"))out.put(field,string(row.get(field)));for(String field:List.of("reason","audit_status","audit_reason"))out.put(field,row.get(field));for(String field:List.of("report_time","reviewed_at"))out.put(field,time(row.get(field)));return out;}
    public Object report(AccountService.Identity actor,long id,JsonNode body,String key){AccountService.fields(body,"reason");String reason=text(body,"reason",1,500);return m.accounts.memberMutation(actor,"message-report:"+id,key,body,()->{message(actor,id,false);if(m.one("SELECT report_id FROM t_msg_report WHERE msg_id=? AND reporter_id=?",id,actor.id())!=null)throw new ApiException(409,"已举报此消息",null,"UNIQUE_CONFLICT");long report=m.insert("INSERT INTO t_msg_report(msg_id,reporter_id,reason) VALUES(?,?,?)",id,actor.id(),reason);return reportView(m.require("t_msg_report","report_id",report,false));});}
    public Object reports(AccountService.Identity actor,int page,int size){return m.page("t_msg_report","*"," WHERE reporter_id=?",List.of(actor.id()),page,size,"report_time DESC,report_id DESC",this::reportView);}
}
